import itertools
import json

def solve_puzzle():
    # Input variables
    houses = [1, 2, 3]  # Left to right as seen from across the street
    names = ["Eric", "Arnold", "Peter"]
    heights = ["short", "very short", "average"]

    solutions = []

    # Enumerate all possible assignments of names and heights to houses
    for name_perm in itertools.permutations(names):
        # name_at_house[h] gives the name at house h (1-indexed)
        name_at_house = {house: name_perm[house - 1] for house in houses}
        pos_of_name = {name_at_house[h]: h for h in houses}

        # Apply name-related constraints early to prune search
        # 1. Eric is not in the first house.
        if pos_of_name["Eric"] == 1:
            continue
        # 4. Arnold is not in the first house.
        if pos_of_name["Arnold"] == 1:
            continue

        for height_perm in itertools.permutations(heights):
            height_at_house = {house: height_perm[house - 1] for house in houses}
            pos_of_height = {height_at_house[h]: h for h in houses}

            # Constraints:
            # 2. The person who is very short is somewhere to the left of the person who is short.
            if not (pos_of_height["very short"] < pos_of_height["short"]):
                continue

            # 3. The person who is very short is Eric.
            if pos_of_name["Eric"] != pos_of_height["very short"]:
                continue

            # If all constraints satisfied, collect solution rows
            rows = []
            for h in houses:
                rows.append([str(h), name_at_house[h], height_at_house[h]])
            solutions.append(rows)

    # Expect exactly one solution
    if len(solutions) != 1:
        raise ValueError(f"Expected a unique solution, found {len(solutions)}")

    solution_rows = solutions[0]
    result = {
        "solution": {
            "header": ["House", "Name", "height"],
            "rows": solution_rows
        }
    }
    return result

if __name__ == "__main__":
    result = solve_puzzle()
    print(json.dumps(result, ensure_ascii=False, indent=2))
